<script setup lang="ts">import { Head,Link,useForm } from '@inertiajs/vue3';import { Button } from '@/components/ui/button';import { Input } from '@/components/ui/input';const props=defineProps<{receivable:any;accounts:any[];now:string}>();const form=useForm({amount:props.receivable.balance_amount,financial_account_id:props.accounts[0]?.id??'',paid_at:props.now,reference:''});const money=(v:number)=>new Intl.NumberFormat('es-CO',{style:'currency',currency:'COP',maximumFractionDigits:0}).format(v||0);</script><template><Head title="Registrar abono"/><main class="flex flex-1 flex-col gap-5 p-4 md:p-6"><header><h1 class="text-2xl font-semibold">Registrar abono</h1><p class="text-sm text-muted-foreground">{{receivable.customer}} · {{receivable.document_number}} · saldo {{money(receivable.balance_amount)}}</p></header><form class="grid max-w-xl gap-4 rounded-xl border bg-card p-5" @submit.prevent="form.post(`/receivables/${receivable.id}/payments`)"><Input v-model.number="form.amount" type="number" min="1" :max="receivable.balance_amount"/><select v-model="form.financial_account_id" class="h-9 rounded-md border bg-transparent px-3 text-sm"><option v-for="a in accounts" :key="a.id" :value="a.id">{{a.name}}</option></select><Input v-model="form.paid_at" type="datetime-local"/><Input v-model="form.reference" placeholder="Referencia opcional"/><p v-if="Object.keys(form.errors).length" class="text-sm text-destructive">{{Object.values(form.errors)[0]}}</p><div class="flex justify-end gap-2"><Button variant="outline" as-child><Link href="/receivables">Cancelar</Link></Button><Button type="submit" :disabled="form.processing">Confirmar abono</Button></div></form></main></template>
